const data = $input.first().json;
const tickets = data.content || data || [];
if (!Array.isArray(tickets) || tickets.length === 0) return [];
return tickets.map(t => ({ json: { ticketId: t.id, numero: t.numero || 'N/A', clientNom: t.clientNom || 'N/A', canal: t.canal || '', description: t.description || '', transcription: t.transcription || '', agenceNom: t.agenceNom || 'N/A', statut: t.statut || '' } }));

const ticketItems = $('Extraire Tickets').all();
const decisionItems = $input.all();
const now = new Date().toLocaleString('fr-FR');

let favorable = 0, defavorable = 0, enEtude = 0, sansDecision = 0;

const rows = ticketItems.map((t, i) => {
  const ticket = t.json;
  const dec = (decisionItems[i] || {}).json || {};

  let decision = dec.decision || dec.finalDecision || null;
  let score = dec.score;
  let source = dec.source || '';
  let motif = dec.motif || dec.overrideMotif || '';
  let hasDecision = !!decision;

  if (!hasDecision) {
    sansDecision++;
    decision = 'EN ATTENTE';
    score = null;
  } else if (decision === 'FAVORABLE') {
    favorable++;
  } else if (decision === 'DEFAVORABLE') {
    defavorable++;
  } else {
    enEtude++;
  }

  const emoji = decision === 'FAVORABLE' ? '&#9989;' : decision === 'DEFAVORABLE' ? '&#10060;' : decision === 'EN ATTENTE' ? '&#9203;' : '&#128269;';
  const color = decision === 'FAVORABLE' ? '#2E7D32' : decision === 'DEFAVORABLE' ? '#C62828' : decision === 'EN ATTENTE' ? '#9E9E9E' : '#F57C00';
  const scoreStr = score != null ? Number(score).toFixed(0) + '/100' : '-';
  const statutBadge = ticket.statut ? '<span style="background:#E3F2FD;color:#1565C0;padding:2px 6px;border-radius:4px;font-size:11px;">' + ticket.statut + '</span>' : '';

  return '<tr>' +
    '<td style="padding:10px;border-bottom:1px solid #eee;font-weight:600;">' + ticket.numero + '</td>' +
    '<td style="padding:10px;border-bottom:1px solid #eee;">' + ticket.clientNom + '</td>' +
    '<td style="padding:10px;border-bottom:1px solid #eee;">' + statutBadge + '</td>' +
    '<td style="padding:10px;border-bottom:1px solid #eee;color:' + color + ';font-weight:700;">' + emoji + ' ' + decision + '</td>' +
    '<td style="padding:10px;border-bottom:1px solid #eee;font-weight:700;text-align:center;">' + scoreStr + '</td>' +
    '<td style="padding:10px;border-bottom:1px solid #eee;font-size:11px;color:#666;">' + source + '</td>' +
    '<td style="padding:10px;border-bottom:1px solid #eee;font-size:11px;">' + motif.substring(0, 80) + '</td>' +
    '</tr>';
}).join('');

const total = ticketItems.length;
const analyzes = total - sansDecision;

const html = '<div style="font-family:Segoe UI,Arial,sans-serif;max-width:800px;margin:0 auto;">' +
  '<div style="background:linear-gradient(135deg,#4A148C,#7B1FA2);color:white;padding:30px;border-radius:12px 12px 0 0;text-align:center;">' +
    '<h1 style="margin:0;font-size:22px;">&#129302; Auto-Analyse IA \u2014 AutoAssist</h1>' +
    '<p style="margin:8px 0 0;opacity:0.9;">' + total + ' tickets \u2022 ' + analyzes + ' avec d\u00e9cision IA</p>' +
    '<p style="margin:4px 0 0;opacity:0.7;font-size:12px;">' + now + '</p>' +
  '</div>' +
  '<div style="background:white;padding:20px;border:1px solid #e0e0e0;">' +
    '<table style="width:100%;margin-bottom:20px;"><tr>' +
      '<td style="background:#E8F5E9;border-radius:8px;padding:15px;text-align:center;width:25%;">' +
        '<div style="font-size:28px;font-weight:700;color:#2E7D32;">' + favorable + '</div>' +
        '<div style="font-size:11px;color:#555;">&#9989; Favorables</div></td>' +
      '<td style="background:#FFEBEE;border-radius:8px;padding:15px;text-align:center;width:25%;">' +
        '<div style="font-size:28px;font-weight:700;color:#C62828;">' + defavorable + '</div>' +
        '<div style="font-size:11px;color:#555;">&#10060; D\u00e9favorables</div></td>' +
      '<td style="background:#FFF3E0;border-radius:8px;padding:15px;text-align:center;width:25%;">' +
        '<div style="font-size:28px;font-weight:700;color:#F57C00;">' + enEtude + '</div>' +
        '<div style="font-size:11px;color:#555;">&#128269; En \u00e9tude</div></td>' +
      '<td style="background:#F5F5F5;border-radius:8px;padding:15px;text-align:center;width:25%;">' +
        '<div style="font-size:28px;font-weight:700;color:#9E9E9E;">' + sansDecision + '</div>' +
        '<div style="font-size:11px;color:#555;">&#9203; En attente</div></td>' +
    '</tr></table>' +
    '<table style="width:100%;border-collapse:collapse;">' +
      '<tr style="background:#EDE7F6;">' +
        '<th style="padding:10px;text-align:left;font-size:12px;">Ticket</th>' +
        '<th style="padding:10px;text-align:left;font-size:12px;">Client</th>' +
        '<th style="padding:10px;text-align:left;font-size:12px;">Statut</th>' +
        '<th style="padding:10px;text-align:left;font-size:12px;">D\u00e9cision IA</th>' +
        '<th style="padding:10px;text-align:center;font-size:12px;">Score</th>' +
        '<th style="padding:10px;text-align:left;font-size:12px;">Source</th>' +
        '<th style="padding:10px;text-align:left;font-size:12px;">Motif</th>' +
      '</tr>' + rows + '</table>' +
  '</div>' +
  '<div style="background:#f8f9fa;padding:15px;border-radius:0 0 12px 12px;text-align:center;border:1px solid #e0e0e0;border-top:none;">' +
    '<a href="http://localhost:3000/tickets" style="color:#7B1FA2;font-weight:700;text-decoration:none;">&#128200; Ouvrir le Dashboard</a>' +
    '<p style="color:#aaa;font-size:10px;margin:8px 0 0;">\u00a9 2026 AutoAssist \u2014 n8n + Gemma 4</p>' +
  '</div>' +
'</div>';

return [{ json: { html: html, subject: '&#129302; Rapport IA \u2014 ' + analyzes + '/' + total + ' tickets analys\u00e9s' } }];
